SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 코드 객체 — 전부 VALID */
SELECT OBJECT_NAME, OBJECT_TYPE, STATUS FROM USER_OBJECTS WHERE OBJECT_NAME IN ('PKG_SCP0016') ORDER BY 1, 2;

/* 2) 컴파일 오류 — 0건 */
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('PKG_SCP0016') ORDER BY NAME, TYPE, SEQUENCE;

/* 3) GTT 구조 — 0건(사내와 다른 GTT 가 있으면 행) */
SELECT E.T AS TABLE_NAME
  FROM (SELECT 'GT_SCP0016_BOD' T, 'DIVISION_ID|VARCHAR2|120|||Y;BOD_ID|VARCHAR2|600|||Y;FROM_SITE|VARCHAR2|120|||Y;TRANSPORT_MODE|VARCHAR2|200|||Y;LT_TOTAL|NUMBER|0|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0016_DATA1' T, 'VERSION_NO|VARCHAR2|200|||Y;DIVISION_ID|VARCHAR2|120|||Y;BIZ_TYPE|VARCHAR2|120|||Y;PROJECT_CODE|VARCHAR2|200|||Y;ITEM_ID|VARCHAR2|200|||Y;ELECTRODE_TYPE|VARCHAR2|120|||Y;ORIGIN_TO_DIVISION_ID|VARCHAR2|120|||Y;TO_SITE|VARCHAR2|120|||Y;INCOTERMS|VARCHAR2|40|||Y;ORIGIN_FROM_DIVISION_ID|VARCHAR2|120|||Y;FROM_SITE|VARCHAR2|120|||Y;MEASURE|VARCHAR2|200|||Y;BOD_ID|VARCHAR2|600|||Y;QTY|NUMBER|0|20|10|Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;PLAN_TYPE|VARCHAR2|200|||Y;SEQ|NUMBER|0|19|0|Y;BIZ_TYPE_NAME|VARCHAR2|120|||Y;NICK_NAME|VARCHAR2|600|||Y;TO_SITE_NAME|VARCHAR2|600|||Y;FROM_SITE_NAME|VARCHAR2|600|||Y;YYYYMMDD|VARCHAR2|32|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0016_PIVOT' T, 'KEY_IDX|VARCHAR2|800|||Y;VERSION_NO|VARCHAR2|200|||Y;DIVISION_ID|VARCHAR2|120|||Y;BIZ_TYPE|VARCHAR2|120|||Y;PROJECT_CODE|VARCHAR2|200|||Y;ITEM_ID|VARCHAR2|200|||Y;ELECTRODE_TYPE|VARCHAR2|120|||Y;ORIGIN_TO_DIVISION_ID|VARCHAR2|120|||Y;TO_SITE|VARCHAR2|120|||Y;INCOTERMS|VARCHAR2|40|||Y;ORIGIN_FROM_DIVISION_ID|VARCHAR2|120|||Y;FROM_SITE|VARCHAR2|120|||Y;TRANSPORT_MODE|VARCHAR2|200|||Y;LT_DAY|VARCHAR2|300|||Y;MEASURE|VARCHAR2|200|||Y;MEASURE_LABEL|VARCHAR2|600|||Y;MEASURE_ORDER_NO|NUMBER|0|10|0|Y;BOD_ID|VARCHAR2|600|||Y;QTY|NUMBER|0|20|10|Y;PLAN_START_YYYYMMDD|VARCHAR2|32|||Y;PLAN_TYPE|VARCHAR2|200|||Y;SEQ|NUMBER|0|19|0|Y;BIZ_TYPE_NAME|VARCHAR2|120|||Y;NICK_NAME|VARCHAR2|600|||Y;TO_SITE_NAME|VARCHAR2|600|||Y;FROM_SITE_NAME|VARCHAR2|600|||Y;FROM_YYYYMMDD|VARCHAR2|32|||Y;TO_YYYYMMDD|VARCHAR2|32|||Y;YYYYMMDD|VARCHAR2|32|||Y;YYYYMM|VARCHAR2|24|||Y;ISO_WEEK|VARCHAR2|24|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_SCP0016_VER' T, 'VERSION_NO|VARCHAR2|200|||Y;CUTOFF_DATE|DATE|0|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'SCP0016' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
