   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0016' MNU_ID, 'main' SHT_NM, 'MEASURE_SELECT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0016' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
