    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'ITEM_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'ITEM_TYPE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'KEY_IDX' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'LT_DAY' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'MEASURE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'MEASURE_LABEL' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'MEASURE_ORDER_NO' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'NICK_NAME' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'ORIGIN_FROM_DIVISION_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'ORIGIN_TO_DIVISION_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'PROJECT_CODE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'PROJECT_NAME' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'PROJECT_OWNER' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'TO_SITE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'TO_SITE_NAME' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'TO_YYYYMMDD' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'TRANSPORT_MODE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Waterfall Shipment Plan' SHEET_NAME, 'VERSION_NO' COLUMN_NAME FROM DUAL) S WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~') AND NVL(TO_CHAR(T.COLUMN_NAME), '~') = NVL(TO_CHAR(S.COLUMN_NAME), '~'));
SELECT 'SCM_MST_SHEET_MEASURE' AS TBL, T.PROGRAM_ID, T.SHEET_NAME, T.COLUMN_NAME
  FROM SCM_MGR.SCM_MST_SHEET_MEASURE T
 WHERE (PROGRAM_ID = 'SCP0016')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'BALANCE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'INTRANSIT' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'MKT_FCST' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'SHIP_PLAN' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'SHIP_PLAN_AMEND' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'SHIP_REQ' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'WH_IN' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0016' PROGRAM_ID, 'Shipment Plan FG' SHEET_NAME, 'WH_IN_TOTAL' COLUMN_NAME FROM DUAL) S WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~') AND NVL(TO_CHAR(T.COLUMN_NAME), '~') = NVL(TO_CHAR(S.COLUMN_NAME), '~'));
